    invalid_price_per_km:"Price must be between 100 and 2000 RWF/km.", invalid_plate:"Plate must look like RAB 123 A.", invalid_vehicle_type:"Choose Moto or Car.",
    division_not_found:"That place is not one of Rwanda's divisions — pick it from the dropdown.", divisions_unavailable:"This server has no division list loaded — try again later.", divisions_unmapped:"We could not match your position to a Rwandan area — use the dropdown.", invalid_location_code:"Pick the place from the province / district / sector dropdown.",
    driver_offline:"That driver is offline right now — pick another.", driver_busy:"That rider already has a passenger — choose another or wait a moment.", service_not_offered:"That driver does not offer this service.", capacity_exceeded:"The vehicle cannot carry that many people.",
