    provider_unreachable:"The payment service did not respond — try again.", paystack_rejected:"Paystack refused this request.", momo_rejected:"MoMo refused this request.", momo_auth_failed:"MoMo rejected the credentials.",
    invalid_status_change:"That status change is not allowed.", empty_update:"Send at least one field.", invalid_json:"The request body was not valid JSON.", server_error:"Server error.",
    unknown_provider:"Unknown payment provider.",
    forbidden:"That action is not allowed for your account.", request_not_found:"That request was not found.", payment_not_found:"That payment was not found.",
    missing_reference:"The payment reference is missing.", bad_webhook_signature:"The provider notification was not verified."
